from django.shortcuts import render, redirect
from django.contrib.auth import login
from .forms import RegistrationForm, EnrollmentForm
from .models import Course, Enrollment

def register(request):
    if request.method == 'POST':
        form = RegistrationForm(request.POST)
        if form.is_valid():
            user = form.save()
            login(request, user)
            return redirect('course_list')
    else:
        form = RegistrationForm()
    return render(request, 'registration/register.html', {'form': form})

def course_list(request):
    courses = Course.objects.all()
    return render(request, 'course_list.html', {'courses': courses})

def course_detail(request, pk):
    course = Course.objects.get(pk=pk)
    if request.method == 'POST':
        form = EnrollmentForm(request.POST)
        if form.is_valid():
            user = request.user
            if Enrollment.objects.filter(user=user, course=course).exists():
                return render(request, 'course_detail.html', {'course': course, 'error': 'You are already enrolled in this course.'})

            if course.capacity <= Enrollment.objects.filter(course=course).count():
                return render(request, 'course_detail.html', {'course': course, 'error': 'Course is full.'})

            enrollment = form.save(commit=False)
            enrollment.user = user
            enrollment.course = course
            enrollment.save()
            return redirect('course_list')
    else:
        form = EnrollmentForm()
    return render(request, 'course_detail.html', {'course': course, 'form': form})
